// app/hifz/plans.ts — memorisation plan definitions (spec §5.2).
//
// Generated by a script (/tmp/gen_hifz.py, kept out of the repo) from the ayah
// counts in ./surahs.ts, then HAND-CHECKED once on 2026-11-21:
//   - every plan's learning days cover the surah's ayahs exactly once,
//     contiguously, never mid-ayah (script assertion + eyeball check);
//   - 7-day plans: days 1–6 learn, day 7 is review (checked on Al-Mulk
//     5 ayahs/day and Al-Kahf 18–19 ayahs/day);
//   - 30-day plans: days 7, 14, 21, 30 are review-only (checked on Al-Mulk
//     and on Al-Ikhlas, whose 4 ayahs are learned on days 1–4 and reviewed
//     for the rest of the month);
//   - Juz Amma 90-day plan: shortest surah first (Al-Asr day 1), every 7th
//     day review, day 90 final review; every Juz Amma surah covered exactly
//     once (script assertion; first 14 and last 8 days eyeballed).
// Regenerate from the script if ayah counts ever change; do not hand-edit
// day ranges. Short surahs front-load their learning days and spend the
// remaining days reviewing — that is deliberate, not an error.
// 30-day plans are Premium in v1: defined here, not billed (spec §3.3/§7).

export interface PlanDay {
  day: number;
  /** First ayah of the day's chunk, or null on a review day. */
  startAyah: number | null;
  /** Last ayah of the day's chunk, or null on a review day. */
  endAyah: number | null;
  label: string;
  isReview: boolean;
}

export interface SurahPlan {
  surahSlug: string;
  surahId: number;
  planDays: 7 | 30;
  days: PlanDay[];
}

/** One day of the Juz Amma 90-day plan: a surah (or part of one), or a review day. */
export interface JuzAmmaPlanDay extends PlanDay {
  /** Surah being learned that day, or null on a review day. */
  surahSlug: string | null;
  surahId: number | null;
}

export interface JuzAmmaPlan {
  planDays: 90;
  days: JuzAmmaPlanDay[];
}

export function getPlan(
  surahSlug: string,
  planDays: 7 | 30,
): SurahPlan | undefined {
  const table = planDays === 7 ? PLANS_7_DAY : PLANS_30_DAY;
  return table[surahSlug];
}

export function getPlanDay(
  plan: SurahPlan | JuzAmmaPlan,
  day: number,
): PlanDay | undefined {
  return plan.days.find((d) => d.day === day);
}

